import { storage } from "@/lib/appwrite";
import { ID } from "appwrite";

// Note: Ensure NEXT_PUBLIC_APPWRITE_BUCKET_ID is set in your .env.local
// If not set, you might need to hardcode it or set it up in Appwrite console.
const BUCKET_ID = process.env.NEXT_PUBLIC_APPWRITE_BUCKET_ID || 'message-attachments';

export const StorageService = {
    async uploadFile(file: File) {
        try {
            return await storage.createFile(
                BUCKET_ID,
                ID.unique(),
                file
            );
        } catch (error) {
            console.error("StorageService.uploadFile error:", error);
            throw error;
        }
    },

    getFileView(fileId: string) {
        return storage.getFileView(BUCKET_ID, fileId);
    },

    getFileDownload(fileId: string) {
        return storage.getFileDownload(BUCKET_ID, fileId);
    },

    getFilePreview(fileId: string, width?: number, height?: number) {
        return storage.getFilePreview(BUCKET_ID, fileId, width, height);
    }
};
