'use client';

import { use, useEffect } from "react";
import ChatArea from "@/components/room/ChatArea";
import RoomDetails from "@/components/room/RoomDetails";
import { useRouter } from "next/navigation";
import { MessagePayload } from "@/types/message";
import { RoomService } from "@/services/room.service";
import { StorageService } from "@/services/storage.service";

// Redux Imports
import { useAppDispatch, useAppSelector } from "@/store/hooks";
import { checkSession } from "@/store/slices/authSlice";
import { enterRoom, joinRoom, exitRoom, fetchRooms } from "@/store/slices/roomSlice"; // fetchRooms used for refresh context if needed
import { fetchMessages, sendMessage } from "@/store/slices/messageSlice";

export default function RoomPage({ params }: { params: Promise<{ roomId: string }> }) {
    const { roomId } = use(params);
    const router = useRouter();
    const dispatch = useAppDispatch();

    // Redux State
    const { user, session, loading: authLoading, initialized: authInitialized } = useAppSelector(state => state.auth);
    const { currentRoom: room, members, loading: roomLoading } = useAppSelector(state => state.rooms);
    const { messages, loading: messagesLoading } = useAppSelector(state => state.messages);

    // Initial Auth Check
    useEffect(() => {
        if (!authInitialized) {
            dispatch(checkSession());
        }
    }, [dispatch, authInitialized]);

    // Auth Protection
    useEffect(() => {
        if (authInitialized && !session) {
            router.push('/session');
        }
    }, [session, authInitialized, router]);

    // Enter Room & Fetch Data
    useEffect(() => {
        if (roomId && session) {
            dispatch(enterRoom(roomId));
            dispatch(fetchMessages(roomId));
        }
        return () => {
            dispatch(exitRoom());
        };
    }, [dispatch, roomId, session]);

    // Join Room Logic (Duplicate guarded by Slice)
    useEffect(() => {
        if (session && user && room && room.$id === roomId) {
            // Dispatch join - slice handles duplication check
            dispatch(joinRoom({
                room: room.$id,
                user: user.userId,
                role: room.creator.$id === user.userId ? 'CREATOR' : 'MEMBER'
            }));
        }
    }, [dispatch, session, user, room, roomId]);

    const handleSendMessage = async (content: string, type: "TEXT" | "IMAGE" | "FILE", file?: File) => {
        if (!user || !room) return;

        let fileId: string | undefined;
        let fileName: string | undefined;
        let fileSize: number | undefined;

        if (file) {
            try {
                const uploaded = await StorageService.uploadFile(file);
                fileId = uploaded.$id;
                fileName = uploaded.name;
                fileSize = uploaded.sizeOriginal;
            } catch (e) {
                console.error("File upload failed", e);
                alert("Failed to upload file");
                return;
            }
        }

        const payload: MessagePayload = {
            room: room.$id,
            sender: user.userId,
            type,
            content,
            fileId,
            fileName,
            fileSize
        };
        // Use Redux action
        dispatch(sendMessage(payload));
    };

    const handleCloseRoom = async () => {
        if (!room) return;
        if (confirm("Are you sure you want to close this room? It will be read-only.")) {
            try {
                await RoomService.close(room.$id);
                // Refresh room state
                dispatch(enterRoom(room.$id));
            } catch (e) {
                console.error(e);
                alert("Failed to close room");
            }
        }
    };

    if (!authInitialized || authLoading) {
        return <div className="h-screen w-full flex items-center justify-center bg-surface-base dark:bg-surface-darkBase text-text-muted dark:text-text-darkMuted">Loading session...</div>;
    }

    if (!session) {
        return null; // Will redirect
    }

    // Combine loading states?
    const isLoading = roomLoading || messagesLoading;
    // Note: room might be null initially while loading

    return (
        <>
            <ChatArea
                room={room}
                messages={messages}
                currentUser={user?.userId || null}
                loading={isLoading}
                onSendMessage={handleSendMessage}
            />
            <RoomDetails
                room={room}
                members={members}
                messages={messages}
                currentUserId={user?.userId || null}
                onCloseRoom={handleCloseRoom}
            />
        </>
    );
}
